############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ $trig = list_random('sin','cos'); $x0 = list_random(0,'pi/2','pi'); ($fp0,$f0) = (2..9)[NchooseK(8,2)]; if($envir{problemSeed}==1){$trig='sin';$x0='pi';$fp0=2;$f0=4;}; Context()->variables->are(theta=>['Real',TeX=>'\theta']); $x0 = Formula("$x0"); $f = Formula("$trig(theta)"); $F = Formula("-$trig(theta)"); $m = $fp0 - $F->D('theta')->eval(theta=>Real("$x0")); $F = Formula("-$trig(theta) + $m theta + ($f0 + $trig($x0) - $m $x0 ) ")->reduce;
############################################################ # Body ############################################################
BEGIN_PGML Find the function determined by the given initial value problem.
[`\fpp(\theta)=[$f]`] and [`\fp\left([$x0]\right)=[$fp0]\text{,}`] [`f\left([$x0]\right)=[$f0]`]
[@KeyboardInstructions('To enter [`\theta\text{,}`] type [|theta|]*.')@]**
[_]{$F}{40}
END_PGML
############################################################ # End Problem ############################################################
ENDDOCUMENT();

